// Датчик протечки воды — XIAO ESP32-C3
// Щуп: PR1.SENSE на D3 (GPIO5) + 100k к V3V3, LOW = вода.
// щуп от пина к GND через воду, подтяжка 100k к V3V3: сухо = HIGH, вода = LOW.
// Пищалка: D10 (GPIO10) -> 1k -> база NPN, активная (DC). LED: D2 (GPIO4) -> 1k -> A.
// Кнопка: D1 (GPIO3) -> GND, INPUT_PULLUP, LOW = нажата.
#define PIN_PROBE 5
#define PIN_BUZZ 10
#define PIN_LED 4
#define PIN_BTN 3
bool muted = false;
unsigned long muteUntil = 0;
unsigned long lastBlink = 0;
bool blinkOn = false;
void alarmOff() { digitalWrite(PIN_BUZZ, LOW); digitalWrite(PIN_LED, LOW); }
void setup() {
  pinMode(PIN_PROBE, INPUT_PULLUP);
  pinMode(PIN_BTN, INPUT_PULLUP);
  pinMode(PIN_BUZZ, OUTPUT);
  pinMode(PIN_LED, OUTPUT);
  alarmOff();
  Serial.begin(115200);
  delay(200);
}
bool probeWet() { int wet = 0; for (int i = 0; i < 5; i++) { if (digitalRead(PIN_PROBE) == LOW) wet++; delay(5); } return wet >= 3; }
bool btnPressed() { return digitalRead(PIN_BTN) == LOW; }
void goSleep() {
  alarmOff();
  esp_deep_sleep_enable_gpio_wakeup((1ULL << PIN_PROBE) | (1ULL << PIN_BTN), ESP_GPIO_WAKEUP_GPIO_LOW);
  Serial.println("sleep"); Serial.flush(); delay(100);
  esp_deep_sleep_start();
}
void loop() {
  static unsigned long drySince = 0;
  static bool hadWater = false;
  bool wet = probeWet();
  static unsigned long pressStart = 0;
  static bool wasPressed = false;
  bool pressed = btnPressed();
  if (pressed && !wasPressed) { pressStart = millis(); }
  if (!pressed && wasPressed) {
    if (wet || hadWater) { muted = true; muteUntil = millis() + 5UL*60UL*1000UL; alarmOff(); }
    else { digitalWrite(PIN_BUZZ, HIGH); digitalWrite(PIN_LED, HIGH); delay(800); alarmOff(); }
  }
  wasPressed = pressed;
  if (pressed && millis() - pressStart > 3000) { muted = false; pressStart = millis(); }
  if (muted && (long)(millis() - muteUntil) >= 0) muted = false;
  if (wet) {
    hadWater = true; drySince = 0;
    if (!muted) {
      digitalWrite(PIN_BUZZ, HIGH);
      if (millis() - lastBlink > 250) { lastBlink = millis(); blinkOn = !blinkOn; digitalWrite(PIN_LED, blinkOn ? HIGH : LOW); }
    } else {
      digitalWrite(PIN_BUZZ, LOW);
      if (millis() - lastBlink > 1000) { lastBlink = millis(); blinkOn = !blinkOn; digitalWrite(PIN_LED, blinkOn ? HIGH : LOW); }
    }
    delay(20); return;
  } else {
    if (hadWater) {
      if (drySince == 0) drySince = millis();
      alarmOff();
      if (millis() - drySince > 10000) { hadWater = false; drySince = 0; goSleep(); }
      delay(50); return;
    }
    static unsigned long bootT = 0;
    if (bootT == 0) bootT = millis();
    alarmOff();
    if (millis() - bootT > 30000) goSleep();
    delay(50);
  }
}

